changeSet.sql:
ALTER TABLE pedido
    ADD CONSTRAINT ck_pedido_valor_total_nao_negativo CHECK (valor_total >= 0);
ALTER TABLE pedido
    ADD CONSTRAINT ck_pedido_taxa_entrega_nao_negativa CHECK (taxa_entrega >= 0);

ALTER TABLE pedido
    ADD CONSTRAINT ck_pedido_status CHECK (status IN
        ('CRIADO','CONFIRMADO','EM_PREPARO','A_CAMINHO','ENTREGUE','CANCELADO'));
ALTER TABLE entregador
    ADD CONSTRAINT ck_entregador_tipo_veiculo CHECK (tipo_veiculo IN
        ('MOTO','BICICLETA','CARRO','A_PE'));
ALTER TABLE pagamento
    ADD CONSTRAINT ck_pagamento_metodo CHECK (metodo IN
        ('CARTAO_CREDITO','CARTAO_DEBITO','PIX','DINHEIRO'));
ALTER TABLE pagamento
    ADD CONSTRAINT ck_pagamento_status CHECK (status IN
        ('PENDENTE','APROVADO','RECUSADO','ESTORNADO'));
ALTER TABLE avaliacao
    ADD CONSTRAINT ck_avaliacao_nota CHECK (nota BETWEEN 1 AND 5);
ALTER TABLE item_pedido
    ADD CONSTRAINT ck_item_pedido_quantidade CHECK (quantidade > 0);
ALTER TABLE item_pedido
    ADD CONSTRAINT ck_item_pedido_preco CHECK (preco_unitario >= 0);
ALTER TABLE item_cardapio
    ADD CONSTRAINT ck_item_cardapio_preco CHECK (preco >= 0);

changeSet.rollback:
ALTER TABLE pedido DROP CONSTRAINT ck_pedido_status;
ALTER TABLE entregador DROP CONSTRAINT ck_entregador_tipo_veiculo;
ALTER TABLE pagamento DROP CONSTRAINT ck_pagamento_metodo;
ALTER TABLE pagamento DROP CONSTRAINT ck_pagamento_status;
ALTER TABLE avaliacao DROP CONSTRAINT ck_avaliacao_nota;
ALTER TABLE item_pedido DROP CONSTRAINT ck_item_pedido_quantidade;
ALTER TABLE item_pedido DROP CONSTRAINT ck_item_pedido_preco;
ALTER TABLE item_cardapio DROP CONSTRAINT ck_item_cardapio_preco;
